def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for src, dst in edges:
        if dst not in adj[src]:
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    current_data = []

    for line in lines:
        if line == '':
            if current_data:
                data = '\n'.join(current_data)
                if data == '[DONE]':
                    return events
                events.append(data)
            current_data = []
        elif line.startswith(':'):
            pass
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            current_data.append(value)
        else:
            pass

    return events

import math


def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    if base >= cap:
        return float(cap)

    # 0 < base < cap: check whether base * 2**attempt >= cap
    # without ever constructing 2**attempt as a huge integer.
    # base * 2**attempt >= cap  <=>  attempt >= log2(cap) - log2(base)
    threshold = math.log2(cap) - math.log2(base)

    if attempt >= threshold:
        return float(cap)

    # Here attempt < threshold, so 2**attempt < cap/base (a finite value).
    # math.ldexp computes base * 2**attempt directly in floating-point
    # arithmetic without constructing an intermediate big integer.
    return math.ldexp(base, attempt)

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError(f"queued reservation {r} exceeds whole budget {budget}")

    remaining_tokens = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    idx = 0
    for item in queued:
        if remaining_slots > 0 and remaining_tokens >= item:
            admitted.append(item)
            remaining_tokens -= item
            remaining_slots -= 1
        else:
            break
        idx += 1

    remaining = list(queued[idx:])
    return (admitted, remaining)
